package com.edusec.backend.model;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Domain model representing a persistent alert generated by the detection engine.
 */
public record Alert(
    String id,
    String ruleId,
    String title,
    String description,
    AlertSeverity severity,
    List<String> relatedEventIds,
    Map<String, Object> evidence,
    String fingerprint,
    AlertStatus status,
    Instant createdAt
) {
    public Alert {
        if (relatedEventIds == null) {
            relatedEventIds = Collections.emptyList();
        } else {
            relatedEventIds = List.copyOf(relatedEventIds);
        }
        if (evidence == null) {
            evidence = Collections.emptyMap();
        } else {
            evidence = Collections.unmodifiableMap(new HashMap<>(evidence));
        }
        if (status == null) {
            status = AlertStatus.OPEN;
        }
    }
}
